package com.fleetcontrol.msroutes.constants;

import java.nio.charset.StandardCharsets;
import java.util.List;
import java.util.UUID;
import lombok.AccessLevel;
import lombok.NoArgsConstructor;

/** Sizes, schedules and catalogue used to generate the demo routes. */
@NoArgsConstructor(access = AccessLevel.PRIVATE)
public final class DemoConstants {

  public static final String DEMO_PROFILE = "demo";

  public static final int DEFAULT_SEED = 42;
  public static final int DEFAULT_DAYS = 90;

  /** Vehicles generated by ms-vehicles: {@code vehicleId(1)} to {@code vehicleId(25)}. */
  public static final int VEHICLE_COUNT = 25;

  /** Drivers generated by ms-drivers: {@code driverId(1)} to {@code driverId(20)}. */
  public static final int DRIVER_COUNT = 20;

  /** Prefix and seed that ms-auth uses to compute the id of the demo admin user. */
  public static final String ADMIN_UUID_PREFIX = "fleetcontrol-ms-auth-admin-";

  /** Routes completed in each shift: between this number and this number plus the range. */
  public static final int MIN_ROUTES_PER_SHIFT = 9;

  public static final int ROUTES_PER_SHIFT_RANGE = 3;

  /** Minutes after midnight (UTC) in which the morning routes start: 04:30 to 06:30. */
  public static final int MORNING_FIRST_MINUTE = 270;

  public static final int MORNING_RANGE_MIN = 120;

  /** Minutes after midnight (UTC) in which the afternoon routes start: 14:00 to 16:00. */
  public static final int AFTERNOON_FIRST_MINUTE = 840;

  public static final int AFTERNOON_RANGE_MIN = 120;

  /** Routes that are planned for the next working days. */
  public static final int PLANNED_ROUTES = 3;

  /** Minutes after midnight (UTC) in which the planned routes start: 08:00. */
  public static final int PLANNED_START_MINUTE = 480;

  /** Share of its estimated duration that a route in progress has already run: 20 % to 80 %. */
  public static final double IN_PROGRESS_MIN_PROGRESS = 0.20;

  public static final double IN_PROGRESS_PROGRESS_RANGE = 0.60;

  public static final int MIN_AVERAGE_SPEED_KMH = 55;
  public static final int AVERAGE_SPEED_RANGE_KMH = 15;
  public static final int MIN_DURATION_MIN = 30;
  public static final int MAX_DURATION_MIN = 300;

  /** The planned distance is the distance of the trip multiplied by 0.95 to 1.05. */
  public static final double PLANNED_DISTANCE_MIN_FACTOR = 0.95;

  public static final double PLANNED_DISTANCE_FACTOR_RANGE = 0.10;

  /** The actual distance is the planned distance multiplied by 0.96 to 1.06. */
  public static final double ACTUAL_DISTANCE_MIN_FACTOR = 0.96;

  public static final double ACTUAL_DISTANCE_FACTOR_RANGE = 0.10;

  /** The actual duration is the estimated one multiplied by 0.90 to 1.15. */
  public static final double ACTUAL_DURATION_MIN_FACTOR = 0.90;

  public static final double ACTUAL_DURATION_FACTOR_RANGE = 0.25;

  /** The route starts between 0 and this number of minutes after the planned start. */
  public static final int MAX_START_DELAY_MIN = 10;

  /** One of every this number of completed routes has a note. */
  public static final int NOTE_FREQUENCY = 4;

  public static final int RETRY_ATTEMPTS = 30;
  public static final long RETRY_DELAY_MS = 5_000L;

  private static final String MADRID = "Madrid - Centro Logístico";
  private static final String VALENCIA = "Valencia - Puerto";

  /** A trip of the catalogue. */
  public record Trip(String origin, String destination, int distanceKm) {}

  public static final List<Trip> TRIPS =
      List.of(
          new Trip(MADRID, "Guadalajara - Polígono Cabanillas", 55),
          new Trip(MADRID, "Toledo - Almacén Sur", 75),
          new Trip(MADRID, "Segovia - Plataforma Logística", 95),
          new Trip(MADRID, "Ávila - Hub Regional", 110),
          new Trip(MADRID, "Cuenca - Centro de Distribución", 170),
          new Trip(MADRID, VALENCIA, 355),
          new Trip(VALENCIA, "Castellón - Polígono Industrial", 75),
          new Trip(VALENCIA, "Teruel - Almacén Central", 150),
          new Trip(VALENCIA, "Alicante - Terminal Logística", 165),
          new Trip(VALENCIA, "Albacete - Plataforma Sur", 185),
          new Trip("Toledo - Almacén Sur", MADRID, 75),
          new Trip("Castellón - Polígono Industrial", VALENCIA, 75));

  public static final List<String> NOTES =
      List.of(
          "Sin incidencias",
          "Retraso por tráfico",
          "Carga entregada completa",
          "Parada técnica en ruta",
          "Entrega fuera de horario acordada");

  /**
   * Id of the demo vehicle with the given number, from 1. It is the same one that ms-vehicles
   * assigns, so no call is needed to know it.
   */
  public static UUID vehicleId(int number) {
    return UUID.nameUUIDFromBytes(("vehicle-" + number).getBytes(StandardCharsets.UTF_8));
  }

  /** Id of the demo driver with the given number, from 1, the same one that ms-drivers assigns. */
  public static UUID driverId(int number) {
    return UUID.nameUUIDFromBytes(("driver-" + number).getBytes(StandardCharsets.UTF_8));
  }

  /** Id of the user that created the demo routes: the demo admin of ms-auth. */
  public static UUID adminId(int seed) {
    return UUID.nameUUIDFromBytes((ADMIN_UUID_PREFIX + seed).getBytes(StandardCharsets.UTF_8));
  }
}
